use tauri_plugin_sql::{Migration, MigrationKind};

/// Connection string used by the frontend (`sqlite:money-manager.db`).
/// Tauri stores it in the OS app-config directory, so the database never
/// lives inside the project or the installed bundle.
const DB_URL: &str = "sqlite:money-manager.db";

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    // The SQL is generated by `bun run db:generate`. Registering the same
    // migration here keeps the desktop schema in sync with the web one.
    let migrations = vec![Migration {
        version: 1,
        description: "create_transactions",
        sql: include_str!("../../drizzle/0000_high_bucky.sql"),
        kind: MigrationKind::Up,
    }];

    tauri::Builder::default()
        .plugin(
            tauri_plugin_sql::Builder::default()
                .add_migrations(DB_URL, migrations)
                .build(),
        )
        .run(tauri::generate_context!())
        .expect("error while running tauri application");
}
